import{_ as r,c as t,o as a,ae as o}from"./chunks/framework.CliRSA9F.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"more/faq.md","filePath":"more/faq.md"}'),i={name:"more/faq.md"};function n(s,e,l,d,c,h){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h3 id="what-are-the-pricing-plans-for-podseo" tabindex="-1">What are the pricing plans for PodSEO? <a class="header-anchor" href="#what-are-the-pricing-plans-for-podseo" aria-label="Permalink to &quot;What are the pricing plans for PodSEO?&quot;">​</a></h3><p>PodSEO offers multiple plans to fit different needs — from independent podcasters to agencies managing multiple shows. Each plan includes different features, such as keyword tracking limits, access to visibility insights, and competitor discovery tools.</p><p>You can find the full breakdown of our pricing and features on our <a href="https://podseo.com/#pricing" target="_blank" rel="noreferrer">Pricing Page</a>.</p><br><h3 id="is-there-a-free-version-of-podseo" tabindex="-1">Is there a free version of PodSEO? <a class="header-anchor" href="#is-there-a-free-version-of-podseo" aria-label="Permalink to &quot;Is there a free version of PodSEO?&quot;">​</a></h3><p>Yes! PodSEO offers a free version with specific limitations — perfect if you&#39;re just getting started. Here&#39;s what you get:</p><p><strong>Free Plan Includes:</strong></p><ul><li><strong><a href="/features/keyword-strategy.html">Keyword Strategy</a></strong>: Up to 5 tracked keywords in total, of which a maximum of 3 can be Primary</li><li><strong><a href="/features/show-visibility.html">Show Visibility</a></strong>: First 4 keyword rankings visible (additional keywords require upgrade)</li><li><strong><a href="/features/planner.html">Planner</a></strong>: Title and Author metadata alignment (Cover Art, Description, and Episode analysis require upgrade)</li><li><strong><a href="/features/keyword-tracker.html">Keyword Tracker</a></strong>: Full access to tracking charts and historical data</li><li><strong>Basic Platform Data</strong>: Rankings across Apple Podcasts, Spotify, Amazon Music, and YouTube Music</li></ul><p><strong>Paid Plan Benefits:</strong></p><ul><li><strong>Full Visibility</strong>: See all keyword rankings in <a href="/features/show-visibility.html">Show Visibility</a></li><li><strong>A much larger keyword allowance</strong>: Podcaster 100, Producer 500, Agency 50,000 tracked keywords in total (the 3-Primary cap stays the same on every plan)</li><li><strong>Complete Metadata Analysis</strong>: Full AI-powered recommendations for Cover Art, Description, and Episodes in the Planner</li><li><strong>Advanced Features</strong>: Enhanced <a href="/features/competitor-finder.html">competitor discovery</a> and premium analytics</li></ul><p>When you&#39;re ready to unlock the full platform, you can upgrade at any time. Learn more on our <a href="https://podseo.com/#pricing" target="_blank" rel="noreferrer">Pricing Page</a>.</p><br><h3 id="what-s-the-difference-between-primary-secondary-and-monitored-keywords" tabindex="-1">What&#39;s the difference between Primary, Secondary, and Monitored keywords? <a class="header-anchor" href="#what-s-the-difference-between-primary-secondary-and-monitored-keywords" aria-label="Permalink to &quot;What&#39;s the difference between Primary, Secondary, and Monitored keywords?&quot;">​</a></h3><p><strong>Primary Keywords</strong> (Maximum 3 on free plan):</p><ul><li>Your most important target keywords for optimization</li><li>Generate the deepest analysis and recommendations</li><li>Should represent your core podcast topics</li></ul><p><strong>Secondary Keywords</strong>:</p><ul><li>Support your primary keyword strategy</li><li>Unlimited on all plans</li><li>Provide broader topic coverage and discovery opportunities</li></ul><p><strong>Monitored Keywords</strong>:</p><ul><li>Keywords you want to monitor but not actively optimize for</li><li>Unlimited on all plans</li><li>Perfect for competitive intelligence and market monitoring</li></ul><p>Learn more about building your keyword strategy in our <a href="/features/keyword-strategy.html">Keyword Strategy guide</a> or follow our step-by-step <a href="/getting-started/workflow.html">PodSEO Workflow</a>.</p><br><h3 id="how-often-should-i-check-my-metadata-alignment" tabindex="-1">How often should I check my metadata alignment? <a class="header-anchor" href="#how-often-should-i-check-my-metadata-alignment" aria-label="Permalink to &quot;How often should I check my metadata alignment?&quot;">​</a></h3><p>We recommend reviewing your metadata alignment in the <a href="/features/planner.html">Planner</a>:</p><ul><li><strong>Initially</strong>: After adding your podcast and setting up your keyword strategy</li><li><strong>After Changes</strong>: Whenever you update your cover art, description, or add new episodes</li><li><strong>Monthly</strong>: As a regular optimization check to discover new opportunities</li><li><strong>Before Big Launches</strong>: Prior to major episode releases or series launches</li></ul><p>Click &quot;Get AI suggestions to improve&quot; in the Planner&#39;s Metadata/Keyword Alignment card for personalized recommendations based on your current keyword strategy.</p><br><h3 id="why-do-i-see-different-rankings-on-different-platforms" tabindex="-1">Why do I see different rankings on different platforms? <a class="header-anchor" href="#why-do-i-see-different-rankings-on-different-platforms" aria-label="Permalink to &quot;Why do I see different rankings on different platforms?&quot;">​</a></h3><p>Each podcasting platform has its own search algorithm and ranking factors:</p><p><strong>Apple Podcasts</strong>: Emphasizes title relevance, category matching, and historical performance <strong>Spotify</strong>: Focuses on engagement metrics, listening patterns, and recommendation signals<br><strong>Amazon Music</strong>: Prioritizes metadata accuracy, category alignment, and cross-platform presence <strong>YouTube Music</strong>: Leverages video engagement, thumbnail optimization, and YouTube ecosystem signals</p><p>This is why PodSEO tracks all major platforms — what works on one platform may need adjustment for others. Use <a href="/features/show-visibility.html">Show Visibility</a> to see your performance across all platforms and <a href="/features/competitive-analysis.html">Competitive Analysis</a> to understand how successful podcasts optimize for different platforms.</p><br><h3 id="what-do-the-search-volume-numbers-mean" tabindex="-1">What do the search volume numbers mean? <a class="header-anchor" href="#what-do-the-search-volume-numbers-mean" aria-label="Permalink to &quot;What do the search volume numbers mean?&quot;">​</a></h3><p>The search volumes shown in PodSEO are scaled for easier comparison between keywords, so focus on the relative differences rather than the absolute numbers. Higher volumes indicate more search interest. Reading the values this way helps you:</p><ul><li>Compare relative keyword popularity at a glance</li><li>Prioritize the keywords with the most search demand</li><li>Make confident decisions about where to focus your optimization</li></ul><br><h3 id="how-long-does-it-take-to-see-results-from-optimization" tabindex="-1">How long does it take to see results from optimization? <a class="header-anchor" href="#how-long-does-it-take-to-see-results-from-optimization" aria-label="Permalink to &quot;How long does it take to see results from optimization?&quot;">​</a></h3><p>Typical optimization timelines:</p><p><strong>Immediate (0-7 days)</strong>:</p><ul><li>Updated metadata appears in platform searches</li><li>New keywords begin tracking in PodSEO</li></ul><p><strong>Short-term (2-4 weeks)</strong>:</p><ul><li>Ranking improvements for targeted keywords</li><li>Increased visibility in platform search results</li></ul><p><strong>Long-term (6-12 weeks)</strong>:</p><ul><li>Significant ranking improvements</li><li>Organic growth in new keyword discoveries</li><li>Platform algorithm recognition of optimization changes</li></ul><p>Consistency in applying recommendations and regular content updates accelerate these results.</p><br><h3 id="what-happens-after-i-add-a-podcast" tabindex="-1">What happens after I add a podcast? <a class="header-anchor" href="#what-happens-after-i-add-a-podcast" aria-label="Permalink to &quot;What happens after I add a podcast?&quot;">​</a></h3><p>When you add a podcast, PodSEO sets up your baseline across Apple Podcasts, Spotify, Amazon Music, and YouTube Music — capturing your current rankings, the keywords you already appear for, and similar podcasts in your category. This gives you a starting point to measure your optimization efforts against.</p><p>Your dashboard will populate as this information becomes available, and you&#39;ll be notified when everything is ready to explore.</p><br><h3 id="can-i-track-keywords-i-m-not-currently-ranking-for" tabindex="-1">Can I track keywords I&#39;m not currently ranking for? <a class="header-anchor" href="#can-i-track-keywords-i-m-not-currently-ranking-for" aria-label="Permalink to &quot;Can I track keywords I&#39;m not currently ranking for?&quot;">​</a></h3><p>Yes! Use <strong>Monitored Keywords</strong> to monitor any keyword, whether you&#39;re currently ranking or not. This is perfect for:</p><ul><li><strong>Competitor Analysis</strong>: Track keywords your competitors rank for</li><li><strong>Market Research</strong>: Monitor emerging trends in your niche</li><li><strong>Future Strategy</strong>: Watch keywords you plan to target later</li><li><strong>Performance Goals</strong>: Track progress toward ranking for new terms</li></ul><p>Monitored keywords don&#39;t count toward your Primary keyword limits and provide valuable competitive intelligence. Learn more in our <a href="/features/keyword-strategy.html">Keyword Strategy guide</a> or explore <a href="/features/competitor-finder.html">competitor discovery tools</a> to find new keywords to track.</p><hr><h2 id="need-more-help" tabindex="-1">Need More Help? <a class="header-anchor" href="#need-more-help" aria-label="Permalink to &quot;Need More Help?&quot;">​</a></h2><ul><li><strong>Getting Started</strong>: Follow our <a href="/getting-started/first-steps.html">step-by-step first steps guide</a> or <a href="/getting-started/workflow.html">PodSEO Workflow</a></li><li><strong>Feature Documentation</strong>: Browse our complete feature guides for detailed instructions</li><li><strong>AI Assistant</strong>: Chat with <a href="/features/lucia-ai-assistant.html">LUCIA</a> for personalized help and answers</li><li><strong>Contact Support</strong>: Reach out via <a href="https://podseo.com/settings/contact" target="_blank" rel="noreferrer">Account Settings &gt; Contact</a> for additional assistance</li></ul>',57)])])}const m=r(i,[["render",n]]);export{u as __pageData,m as default};
